MERGE `{{params.project_name}}.semantics_central.FinancingEligibilityCheck` final
USING (
{{range_query}}
) staging
ON final.financing_eligibility_check_id = staging.financing_eligibility_check_id
WHEN MATCHED THEN
UPDATE SET
final.loan_id = staging.loan_id,
final.loan_from = staging.loan_from,
final.loan_to = staging.loan_to,
final.is_overdue_check = staging.is_overdue_check,
final.is_credit_limit_check = staging.is_credit_limit_check,
final.is_customer_manually_freezed_check = staging.is_customer_manually_freezed_check,
final.is_ltv_check = staging.is_ltv_check,
final.is_customer_financing_status_check = staging.is_customer_financing_status_check,
final.is_admin_status_check = staging.is_admin_status_check,
final.created_at = staging.created_at,
final.updated_at = staging.updated_at,
final.deleted_at = staging.deleted_at,
final.created_by_name = staging.created_by_name,
final.created_by_id = staging.created_by_id,
final.updated_by_name = staging.updated_by_name, 
final.updated_by_id = staging.updated_by_id,
final.deleted_by_name = staging.deleted_by_name, 
final.deleted_by_id = staging.deleted_by_id,
final.unjust_car_rejection = staging.unjust_car_rejection,
final.account_blocked = staging.account_blocked,
final.payment_delayed = staging.payment_delayed,
final.country_id = staging.country_id
WHEN NOT MATCHED THEN
INSERT (
financing_eligibility_check_id,
loan_id,
loan_from,
loan_to,
is_overdue_check,
is_credit_limit_check,
is_customer_manually_freezed_check,
is_ltv_check,
is_customer_financing_status_check,
is_admin_status_check,
created_at,
updated_at,
deleted_at,
created_by_name,
created_by_id,
updated_by_name, 
updated_by_id,
deleted_by_name, 
deleted_by_id,
unjust_car_rejection,
account_blocked,
payment_delayed,
country_id
) VALUES (
staging.financing_eligibility_check_id,
staging.loan_id,
staging.loan_from,
staging.loan_to,
staging.is_overdue_check,
staging.is_credit_limit_check,
staging.is_customer_manually_freezed_check,
staging.is_ltv_check,
staging.is_customer_financing_status_check,
staging.is_admin_status_check,
staging.created_at,
staging.updated_at,
staging.deleted_at,
staging.created_by_name,
staging.created_by_id,
staging.updated_by_name, 
staging.updated_by_id,
staging.deleted_by_name, 
staging.deleted_by_id,
staging.unjust_car_rejection,
staging.account_blocked,
staging.payment_delayed,
staging.country_id
)